"""Provider notification adapter for the billing service.

Accepts the current v1 body digest (``X-Pay-Signature: v1=<hex>``) and the
legacy r0 receipt (``X-Pay-Receipt: r0=<hex>``) carried by the installed v0
connector, which forwards reformatted bodies without a usable v1 digest.
"""

import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

_WINDOW_SECONDS = 300
_TIMESTAMP = re.compile(r"[0-9]+\Z")
_HEX_DIGEST = re.compile(r"[0-9a-fA-F]{64}\Z")
_CURRENCY = re.compile(r"[A-Z]{3}\Z")


def _header(headers, name):
    """Return the first header value matching ``name`` case-insensitively."""
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == name and isinstance(value, str):
            return value
    return None


def _timestamp_in_window(headers, now):
    timestamp = _header(headers, "x-pay-timestamp")
    if timestamp is None or _TIMESTAMP.fullmatch(timestamp) is None:
        raise InvalidNotification("missing or malformed X-Pay-Timestamp")
    if abs(int(timestamp) - now) > _WINDOW_SECONDS:
        raise InvalidNotification("X-Pay-Timestamp outside the acceptance window")
    return timestamp


def _digest_matches(secret, message, candidate):
    """Constant-time check that ``candidate`` is the hex SHA-256 HMAC of ``message``."""
    if candidate is None or _HEX_DIGEST.fullmatch(candidate) is None:
        return False
    expected = hmac.new(secret, message, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, candidate.lower())


def _load_event(raw_body):
    try:
        payload = json.loads(raw_body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        raise InvalidNotification("body is not valid UTF-8 JSON") from None
    if not isinstance(payload, dict):
        raise InvalidNotification("body is not a JSON object")
    return payload


def _normalized(payload):
    event_id = payload.get("event_id")
    account_id = payload.get("account_id")
    amount_minor = payload.get("amount_minor")
    currency = payload.get("currency")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("event_id must be a nonempty string")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("account_id must be a nonempty string")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int) or amount_minor < 0:
        raise InvalidNotification("amount_minor must be a nonnegative integer")
    if not isinstance(currency, str) or _CURRENCY.fullmatch(currency) is None:
        raise InvalidNotification("currency must be three uppercase ASCII letters")
    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if isinstance(secret, str):
        secret = secret.encode("utf-8")
    raw_body = bytes(raw_body)

    timestamp = _timestamp_in_window(headers, now)
    payload = _load_event(raw_body)

    signature = _header(headers, "x-pay-signature")
    if signature is not None and signature.startswith("v1="):
        message = timestamp.encode("ascii") + b"." + raw_body
        if _digest_matches(secret, message, signature[len("v1="):]):
            return _normalized(payload)

    receipt = _header(headers, "x-pay-receipt")
    if receipt is not None and receipt.startswith("r0="):
        event_id = payload.get("event_id")
        if isinstance(event_id, str) and event_id:
            message = timestamp.encode("ascii") + b"." + event_id.encode("utf-8")
            if _digest_matches(secret, message, receipt[len("r0="):]):
                return _normalized(payload)

    raise InvalidNotification("notification signature or receipt does not match")
