{"cmd": "cd /testbed && cat > tests/test_receiver_r0.py <<'EOF'
import hashlib
import hmac
import json
import unittest

from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

SECRET = b"public-test-provider-secret"
NOW = 1760000000


def receipt_for(event_id, stamp=str(NOW)):
    digest = hmac.new(SECRET, stamp.encode() + b"." + event_id.encode(), hashlib.sha256).hexdigest()
    return "r0=" + digest


def body(event, **reformat):
    return json.dumps(event, ensure_ascii=False, **reformat).encode()


class LegacyReceiptMigration(unittest.TestCase):
    def test_reformatted_body_with_receipt_and_no_v1(self):
        event = {"event_id": "evt-r0", "account_id": "acct-r0", "amount_minor": 55,
                 "currency": "USD"}
        reformatted = body(dict(event, provider_note="café"), indent=2)
        headers = {"X-Pay-Timestamp": str(NOW), "X-Pay-Receipt": receipt_for(event["event_id"])}
        self.assertEqual(parse_payment(reformatted, headers, SECRET, NOW), event)

    def test_receipt_accepted_when_v1_digest_mismatches(self):
        event = {"event_id": "evt-r1", "account_id": "acct-r1", "amount_minor": 9,
                 "currency": "EUR"}
        wire = body(event)
        good_stamp = str(NOW)
        bad_v1 = hmac.new(SECRET, good_stamp.encode() + b"." + wire + b" ",
                          hashlib.sha256).hexdigest()
        headers = {"X-Pay-Timestamp": good_stamp,
                   "X-Pay-Signature": "v1=" + bad_v1,
                   "X-Pay-Receipt": receipt_for(event["event_id"])}
        self.assertEqual(parse_payment(wire, headers, SECRET, NOW), event)

    def test_receipt_with_matching_v1_still_uses_v1_form(self):
        event = {"event_id": "evt-r2", "account_id": "acct-r2", "amount_minor": 0,
                 "currency": "USD"}
        wire = body(event)
        stamp = str(NOW)
        v1 = hmac.new(SECRET, stamp.encode() + b"." + wire, hashlib.sha256).hexdigest()
        headers = {"X-Pay-Timestamp": stamp,
                   "X-Pay-Signature": "v1=" + v1,
                   "X-Pay-Receipt": receipt_for(event["event_id"])}
        self.assertEqual(parse_payment(wire, headers, SECRET, NOW), event)

    def test_unicode_event_and_account_ids(self):
        event = {"event_id": "evt-€1", "account_id": "客户-café", "amount_minor": 3,
                 "currency": "USD"}
        headers = {"X-Pay-Timestamp": str(NOW), "X-Pay-Receipt": receipt_for(event["event_id"])}
        self.assertEqual(parse_payment(body(event), headers, SECRET, NOW), event)

    def test_stale_receipt_rejected(self):
        event = {"event_id": "evt-r3", "account_id": "acct-r3", "amount_minor": 1,
                 "currency": "USD"}
        stale = str(NOW + 301)
        headers = {"X-Pay-Timestamp": stale, "X-Pay-Receipt": receipt_for(event["event_id"], stale)}
        with self.assertRaises(InvalidNotification):
            parse_payment(body(event), headers, SECRET, NOW)

    def test_receipt_over_other_event_id_rejected(self):
        event = {"event_id": "evt-r4", "account_id": "acct-r4", "amount_minor": 1,
                 "currency": "USD"}
        headers = {"X-Pay-Timestamp": str(NOW), "X-Pay-Receipt": receipt_for("evt-other")}
        with self.assertRaises(InvalidNotification):
            parse_payment(body(event), headers, SECRET, NOW)

    def test_receipt_with_wrong_secret_rejected(self):
        event = {"event_id": "evt-r5", "account_id": "acct-r5", "amount_minor": 1,
                 "currency": "USD"}
        digest = hmac.new(b"other-secret", str(NOW).encode() + b"." + b"evt-r5",
                          hashlib.sha256).hexdigest()
        headers = {"X-Pay-Timestamp": str(NOW), "X-Pay-Receipt": "r0=" + digest}
        with self.assertRaises(InvalidNotification):
            parse_payment(body(event), headers, SECRET, NOW)

    def test_no_proof_rejected(self):
        event = {"event_id": "evt-r6", "account_id": "acct-r6", "amount_minor": 1,
                 "currency": "USD"}
        headers = {"X-Pay-Timestamp": str(NOW)}
        with self.assertRaises(InvalidNotification):
            parse_payment(body(event), headers, SECRET, NOW)

    def test_receipt_with_invalid_field_rejected(self):
        event = {"event_id": "evt-r7", "account_id": "acct-r7", "amount_minor": True,
                 "currency": "USD"}
        headers = {"X-Pay-Timestamp": str(NOW), "X-Pay-Receipt": receipt_for(event["event_id"])}
        with self.assertRaises(InvalidNotification):
            parse_payment(body(event), headers, SECRET, NOW)


if __name__ == "__main__":
    unittest.main()
EOF
