import hashlib, hmac, json
from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

S = b"secret"; NOW = 1760000000
ev = {"event_id": "e1", "account_id": "a1", "amount_minor": 10, "currency": "USD"}
b = json.dumps(ev).encode()
r0 = "r0=" + hmac.new(S, b"1760000000" + b"." + b"e1", hashlib.sha256).hexdigest()

# unknown sig scheme falls through to r0
h = {"X-Pay-Timestamp": "1760000000", "X-Pay-Signature": "v2=" + "0"*64, "X-Pay-Receipt": r0}
print("v2-scheme + r0:", parse_payment(b, h, S, NOW)["currency"])

# case-insensitive headers
print("ci headers:", parse_payment(b, {"x-pay-timestamp": "1760000000", "x-Pay-RECEIPT": r0}, S, NOW)["account_id"])

# float amount rejected
bad = dict(ev, amount_minor=10.0)
try: parse_payment(json.dumps(bad).encode(), {"X-Pay-Timestamp": "1760000000", "X-Pay-Receipt": r0}, S, NOW)
except InvalidNotification as e: print("float amount:", e)

# malformed JSON rejected on r0 path
try: parse_payment(b"not json", {"X-Pay-Timestamp": "1760000000", "X-Pay-Receipt": r0}, S, NOW)
except InvalidNotification as e: print("bad json:", e)

# negative amount rejected
bad = dict(ev, amount_minor=-5)
try: parse_payment(json.dumps(bad).encode(), {"X-Pay-Timestamp": "1760000000", "X-Pay-Receipt": r0}, S, NOW)
except InvalidNotification as e: print("negative amount:", e)

# boundary: exactly 300s accepted, 301 rejected (v1)
v1 = "v1=" + hmac.new(S, b"1760000000" + b"." + b, hashlib.sha256).hexdigest()
print("window edge ok:", parse_payment(b, {"X-Pay-Timestamp": "1760000000", "X-Pay-Signature": v1}, S, NOW + 300)["event_id"])
try: parse_payment(b, {"X-Pay-Timestamp": "1760000000", "X-Pay-Signature": v1}, S, NOW + 301)
except InvalidNotification as e: print("window edge reject:", e)

# str secret accepted
print("str secret:", parse_payment(b, {"X-Pay-Timestamp": "1760000000", "X-Pay-Receipt": "r0=" + hmac.new(b"secret2", b"1760000000" + b"." + b"e1", hashlib.sha256).hexdigest()}, "secret2", NOW)["event_id"])

# result is a fresh dict with exactly the four keys
out = parse_payment(b, {"X-Pay-Timestamp": "1760000000", "X-Pay-Receipt": r0}, S, NOW)
print("keys:", sorted(out), type(out).__name__)
